# AP World Unit 9 sources. Texts follow the editions saved in aw9/sources/raw/ and documented in
# aw9/sources/*.md. Cuts are marked with ellipses; bracketed words are clarifications.
# Copyright basis (see each .md): works of the U.S. government (speeches of U.S. officials, the
# Congressional Record, FRUS, FBIS translations, NASA and U.S. Army photographs); official texts of
# other states (China Copyright Law Art. 5; South Africa Copyright Act s.12(8)(a); Mexico LFDA Art. 14;
# treaty texts); United Nations General Assembly resolutions and the UDHR; Hansard (1927) and other
# texts published before 1931; and open data under CC BY 4.0 (World Bank WDI; Global Carbon Budget via
# Our World in Data). No copyrighted post-1930 non-government text is used.
VERSION = "2026-11-08b"

def P(paragraphs, attribution, translation="", footnotes=None, glossary=None, **kw):
    d = {"type": "passage", "paragraphs": paragraphs, "attribution": attribution}
    if translation: d["translation"] = translation
    if footnotes: d["footnotes"] = footnotes
    if glossary: d["glossary"] = glossary
    d.update(kw)
    return d

def item(label, paragraphs, attribution, translation="", footnotes=None, glossary=None):
    d = {"label": label, "paragraphs": paragraphs, "attribution": attribution}
    if translation: d["translation"] = translation
    if footnotes: d["footnotes"] = footnotes
    if glossary: d["glossary"] = glossary
    return d

